import 'vuetify/src/stylus/app.styl'
import es from 'vuetify/es5/locale/es'
import Vue from 'vue'
import Vuetify from 'vuetify'
import 'vuetify/dist/vuetify.min.css'
Vue.use(Vuetify, {
  theme: {

    primary: '#1976D2',
    secondary: '#424242',
    accent: '#82B1FF',
    error: '#FF5252',
    info: '#2196F3',
    success: '#4CAF50',
    warning: '#FFC107',
    cabecera:'#FB8C00',
    colorCabecera:'#FFFFFF',



  },
  options: {
    customProperties: true
  },
  iconfont: 'mdi',
  lang: {
    locales: { es },
    current: 'es'
  },
})
